// Who gets a report in this run, and which symbols we need to fetch (once, for everyone).
// Scheduled runs skip anyone who already got today's scheduled report: running twice never sends twice.
let run;
try { run = $('Scheduled Run Settings').first().json; } catch (e) { run = $('On-Demand Run Settings').first().json; }
const today = $now.setZone('Europe/Paris').toFormat('yyyy-MM-dd');
const subs = $('Read Active Subscribers').all().map(i => i.json).filter(s => s.chat_id);
const watch = $('Read All Watchlists').all().map(i => i.json).filter(w => w.chat_id && w.symbol);
const log = $('Read Todays Report Log').all().map(i => i.json).filter(l => l.chat_id);
const alreadySent = new Set(log.filter(l => l.trigger === 'scheduled' && l.status === 'sent').map(l => String(l.chat_id)));
const INDICES = ['^GSPC', '^IXIC', '^DJI'];
let recipients = [];
if (run.mode === 'scheduled') {
  recipients = subs.filter(s => !alreadySent.has(String(s.chat_id)))
    .map(s => ({ chat_id: String(s.chat_id), first_name: s.first_name || '' }));
} else if (run.chat_id) {
  const s = subs.find(x => String(x.chat_id) === String(run.chat_id));
  recipients = [{ chat_id: String(run.chat_id), first_name: s ? (s.first_name || '') : '' }];
}
recipients = recipients.map(r => Object.assign(r, {
  symbols: watch.filter(w => String(w.chat_id) === r.chat_id).map(w => String(w.symbol).toUpperCase())
}));
const symbols = Array.from(new Set(INDICES.concat(...recipients.map(r => r.symbols))));
return [{ json: {
  mode: run.mode, today: today, recipients: recipients, symbols: symbols,
  skipped_already_sent: run.mode === 'scheduled' ? subs.length - recipients.length : 0,
  has_recipients: recipients.length > 0
} }];

// Gather every section in one place. Each section succeeds or fails on its own:
// a dead source marks its section as unavailable instead of stopping the whole report.
const plan = $('Pick Recipients').first().json;
const safeAll = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const safeFirst = name => { try { return $(name).first().json; } catch (e) { return {}; } };

// Stocks and indices (from the Get Market Quotes sub-workflow)
const qp = safeFirst('Get Market Quotes');
const quotes = Array.isArray(qp.quotes) ? qp.quotes : [];
const okQuotes = quotes.filter(q => q.ok);
const bySymbol = {};
for (const q of quotes) bySymbol[q.symbol] = q;
let stocks = 'down';
if (okQuotes.length === quotes.length && quotes.length) stocks = 'ok';
else if (okQuotes.length) stocks = 'partial';
const usedBackup = okQuotes.some(q => q.source === 'alphavantage');

// Currencies: Frankfurter (with day-over-day change), else the backup (rate only)
let fx = { status: 'down' };
const f = safeFirst('Fetch FX Rates');
if (f && f.rates && typeof f.rates === 'object' && Object.keys(f.rates).length) {
  const dates = Object.keys(f.rates).sort();
  const last = f.rates[dates[dates.length - 1]].EUR;
  const prev = dates.length > 1 ? f.rates[dates[dates.length - 2]].EUR : null;
  fx = { status: 'ok', source: 'frankfurter', usd_eur: last, eur_usd: 1 / last,
         change_pct: prev ? (last - prev) / prev * 100 : null, as_of: dates[dates.length - 1] };
} else {
  const b = safeFirst('Fetch FX Backup Rate');
  if (b && b.result === 'success' && b.rates && b.rates.EUR) {
    fx = { status: 'backup', source: 'exchangerate-api', usd_eur: b.rates.EUR, eur_usd: 1 / b.rates.EUR, change_pct: null };
  }
}

// Headlines: three feeds, duplicates removed, last 36 hours, newest first
const feeds = [['Read CNBC Market Headlines', 'CNBC'], ['Read BBC Business Headlines', 'BBC'], ['Read Political Headlines', 'Google News']];
const seen = new Set();
let headlines = [];
let feedsOk = 0;
for (const pair of feeds) {
  // At most 4 newest per feed, so one busy source cannot crowd out the others.
  const rows = safeAll(pair[0]).filter(r => r.title && r.link && !r.error)
    .sort((a, b) => new Date(b.isoDate || b.pubDate || 0) - new Date(a.isoDate || a.pubDate || 0)).slice(0, 4);
  if (rows.length) feedsOk++;
  for (const r of rows) {
    const key = String(r.title).toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 60);
    if (seen.has(key)) continue;
    seen.add(key);
    const date = new Date(r.isoDate || r.pubDate || 0);
    let title = String(r.title).trim();
    let source = pair[1];
    if (pair[1] === 'Google News' && title.lastIndexOf(' - ') > 0) {
      source = title.slice(title.lastIndexOf(' - ') + 3);
      title = title.slice(0, title.lastIndexOf(' - '));
    }
    headlines.push({ title: title, link: r.link, source: source, ts: isNaN(date) ? 0 : date.getTime() });
  }
}
const cutoff = Date.now() - 36 * 3600 * 1000;
headlines = headlines.filter(h => h.ts === 0 || h.ts >= cutoff).sort((a, b) => b.ts - a.ts).slice(0, 12)
  .map((h, i) => Object.assign(h, { id: i + 1 }));
const news = headlines.length ? (feedsOk === feeds.length ? 'ok' : 'partial') : 'down';

// What the AI is allowed to see: compact, numbers already computed by code
const indexNames = { '^GSPC': 'S&P 500', '^IXIC': 'Nasdaq', '^DJI': 'Dow Jones' };
const round = (x, d) => (x === null || x === undefined || isNaN(x)) ? null : Math.round(x * Math.pow(10, d)) / Math.pow(10, d);
const watched = okQuotes.filter(q => !indexNames[q.symbol]);
const movers = watched.slice().sort((a, b) => Math.abs(b.change_pct || 0) - Math.abs(a.change_pct || 0)).slice(0, 8);
const aiInput = {
  indices: Object.keys(indexNames).filter(s => bySymbol[s] && bySymbol[s].ok).map(s => ({ name: indexNames[s], change_pct: round(bySymbol[s].change_pct, 2) })),
  followed_stocks_biggest_moves: movers.map(q => ({ symbol: q.symbol, name: q.name, change_pct: round(q.change_pct, 2) })),
  usd_to_eur: fx.status === 'down' ? null : { rate: round(fx.usd_eur, 4), change_pct: round(fx.change_pct, 2) },
  headlines: headlines.map(h => ({ id: h.id, title: h.title, source: h.source }))
};

const down = [];
if (stocks !== 'ok') down.push('stocks:' + stocks);
if (fx.status !== 'ok') down.push('fx:' + fx.status);
if (news !== 'ok') down.push('news:' + news);

return [{ json: {
  today: plan.today, mode: plan.mode, recipients: plan.recipients,
  quotes: bySymbol, fx: fx, headlines: headlines,
  sections: { stocks: stocks, stocks_backup_used: usedBackup, primary_state: qp.primary ? qp.primary.state : 'unknown', fx: fx.status, news: news },
  sections_down: down.join(', '),
  ai_input: aiInput
} }];

// One row per symbol per day, so the system keeps a history it can compare against later.
const d = $input.first().json;
return Object.values(d.quotes).filter(q => q.ok).map(q => ({ json: {
  report_date: d.today, symbol: q.symbol, price: q.price, change_pct: q.change_pct, source: q.source
} }));

// Never trust what a model wrote. Every number in the AI summary must exist in our data,
// and advice words are forbidden. If anything fails, a plain template written by code is used instead.
const d = $('Assemble Market Data').first().json;
const inp = $input.first().json || {};
let ai = inp.output;
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = null; } }
let reason = null;
if (!ai || typeof ai !== 'object') {
  if (inp.error) reason = 'AI call failed';
  else reason = 'AI switched off';
}
const allowed = [];
// The AI sees values rounded to 2 decimals and may round again to 1, so accept both the exact and the 2-decimal value.
const addAllowed = v => { allowed.push(Math.abs(v)); allowed.push(Math.round(Math.abs(v) * 100) / 100); };
for (const q of Object.values(d.quotes)) if (q.ok && typeof q.change_pct === 'number') addAllowed(q.change_pct);
if (d.fx && typeof d.fx.change_pct === 'number') addAllowed(d.fx.change_pct);
const numberOk = n => allowed.some(v => Math.abs(n - v) <= 0.051);
let summary = ai && typeof ai.summary === 'string' ? ai.summary.trim() : '';
if (!reason) {
  if (!summary) reason = 'AI gave an empty summary';
  else if (summary.length > 400) reason = 'AI summary too long';
  else if (/\b(buy|sell|should|recommend|guarantee)/i.test(summary)) reason = 'AI gave advice';
  else {
    // Names can contain digits ("S&P 500"); remove index and company names before checking numbers.
    let scan = summary.replace(/S&P\s*500/gi, 'S&P');
    for (const q of Object.values(d.quotes)) { if (q.name) scan = scan.split(q.name).join(' '); if (q.symbol) scan = scan.split(q.symbol).join(' '); }
    const nums = (scan.match(/\d+(?:[.,]\d+)?/g) || []).map(x => parseFloat(x.replace(',', '.')));
    const bad = nums.filter(n => !numberOk(n));
    if (bad.length) reason = 'AI wrote a number not in the data: ' + bad.join(', ');
  }
}
let ids = ai && Array.isArray(ai.headline_ids) ? ai.headline_ids.map(Number).filter(n => Number.isInteger(n) && n >= 1 && n <= d.headlines.length) : [];
ids = Array.from(new Set(ids)).slice(0, 4);
if (!ids.length) ids = d.headlines.slice(0, 4).map(h => h.id);
if (reason) {
  const fmt = v => (v >= 0 ? '+' : '') + v.toFixed(1) + '%';
  const parts = [];
  const idx = [['^GSPC', 'S&P 500'], ['^IXIC', 'Nasdaq']].filter(p => d.quotes[p[0]] && d.quotes[p[0]].ok);
  if (idx.length) parts.push(idx.map(p => p[1] + ' ' + fmt(d.quotes[p[0]].change_pct)).join(', ') + '.');
  const mv = d.ai_input.followed_stocks_biggest_moves[0];
  if (mv && typeof mv.change_pct === 'number') parts.push('Biggest move among followed stocks: ' + mv.name + ' (' + fmt(mv.change_pct) + ').');
  if (d.fx && d.fx.usd_eur) parts.push('1 dollar buys ' + d.fx.usd_eur.toFixed(4) + ' euros.');
  summary = parts.join(' ') || 'Market data is limited this morning; see the sections below.';
}
return [{ json: { summary: summary, summary_by: reason ? 'template' : 'ai', check_note: reason || 'passed', headline_ids: ids } }];

// One personal message per recipient: shared market sections + their own stocks.
const d = $('Assemble Market Data').first().json;
const s = $input.first().json;
const esc = t => String(t === undefined || t === null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pct = v => (typeof v !== 'number' || isNaN(v)) ? 'n/a' : (v > 0 ? '▲ +' : v < 0 ? '▼ ' : '• ') + v.toFixed(2) + '%';
const num = v => Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const nowNY = $now.setZone('America/New_York');
const head = $now.setZone('Europe/Paris').toFormat('ccc d LLL yyyy');

// When are these prices from? Live during US trading hours, otherwise the last close.
let asOf = '';
const ref = d.quotes['^GSPC'] && d.quotes['^GSPC'].ok ? d.quotes['^GSPC'] : Object.values(d.quotes).find(q => q.ok);
if (ref && ref.market_time) {
  const mt = DateTime.fromISO(ref.market_time).setZone('America/New_York');
  const minutes = nowNY.hour * 60 + nowNY.minute;
  const open = nowNY.weekday <= 5 && minutes >= 570 && minutes < 960 && mt.hasSame(nowNY, 'day');
  asOf = open ? 'Live prices, US market open' : 'Prices as of US close, ' + mt.toFormat('ccc d LLL');
}

const notes = [];
if (d.sections.stocks === 'down') notes.push('Stock prices are unavailable right now (both sources failed). The rest of your report is complete.');
else if (d.sections.stocks_backup_used) notes.push('Some prices came from the backup source (Alpha Vantage) because Yahoo Finance was unavailable' + (d.sections.primary_state === 'circuit_open' ? ' (skipped after repeated failures)' : '') + '.');
if (d.fx.status === 'backup') notes.push('Exchange rate came from the backup source; day-over-day change not available.');
if (d.fx.status === 'down') notes.push('Exchange rates are unavailable right now.');
if (d.sections.news === 'down') notes.push('Headlines are unavailable right now.');

const lines = [];
const indexRows = [['^GSPC', 'S&P 500'], ['^IXIC', 'Nasdaq'], ['^DJI', 'Dow Jones']].map(p => {
  const q = d.quotes[p[0]];
  if (!q || !q.ok) return p[1] + ': unavailable';
  if (q.proxy) return p[1] + ' (via ' + q.proxy + ' fund) ' + pct(q.change_pct);
  return p[1] + '  ' + num(q.price) + '  ' + pct(q.change_pct);
});
const picked = s.headline_ids.map(id => d.headlines.find(h => h.id === id)).filter(Boolean);

// If the backup source was used it has no company names; fall back to the name saved with the watchlist.
const savedNames = {};
try { for (const w of $('Read All Watchlists').all()) if (w.json.symbol && w.json.name) savedNames[String(w.json.symbol).toUpperCase()] = w.json.name; } catch (e) {}
const nameOf = q => (q.name && q.name !== q.symbol) ? q.name : (savedNames[q.symbol] || '');

return d.recipients.map(r => {
  const out = [];
  out.push('📊 <b>Market Report</b> · ' + esc(head));
  if (asOf) out.push('<i>' + esc(asOf) + '</i>');
  out.push('');
  out.push('🧠 <b>In short</b> <i>(' + (s.summary_by === 'ai' ? 'AI-written, fact-checked' : 'automatic summary') + ')</i>');
  out.push(esc(s.summary));
  out.push('');
  out.push('🇺🇸 <b>Indices</b>');
  for (const row of indexRows) out.push(esc(row));
  out.push('');
  out.push('⭐ <b>Your stocks</b>');
  if (!r.symbols.length) out.push('You do not follow any stocks yet. Try /watch AAPL');
  else {
    const mine = r.symbols.map(sym => d.quotes[sym] || { symbol: sym, ok: false });
    const ok = mine.filter(q => q.ok).sort((a, b) => (b.change_pct || 0) - (a.change_pct || 0));
    for (const q of ok) out.push('<b>' + esc(q.symbol) + '</b> ' + esc(nameOf(q)) + '  ' + num(q.price) + ' ' + esc(q.currency || '') + '  ' + pct(q.change_pct));
    const missing = mine.filter(q => !q.ok).map(q => q.symbol);
    if (missing.length) out.push('<i>No data right now for: ' + esc(missing.join(', ')) + '</i>');
  }
  out.push('');
  out.push('💱 <b>Currencies</b>');
  if (d.fx.status === 'down') out.push('Unavailable');
  else {
    out.push('1 USD = ' + d.fx.usd_eur.toFixed(4) + ' EUR' + (typeof d.fx.change_pct === 'number' ? '  ' + pct(d.fx.change_pct) : ''));
    out.push('1 EUR = ' + d.fx.eur_usd.toFixed(4) + ' USD');
  }
  out.push('');
  out.push('📰 <b>Headlines</b>');
  if (!picked.length) out.push('Unavailable');
  for (const h of picked) out.push('• <a href="' + esc(h.link) + '">' + esc(h.title) + '</a> · ' + esc(h.source));
  if (notes.length) { out.push(''); for (const n of notes) out.push('⚠️ ' + esc(n)); }
  out.push('');
  out.push('<i>Information only, not financial advice.</i> /help');
  let text = out.join('\n');
  if (text.length > 4000) text = text.slice(0, 3990) + '…';
  return { json: { chat_id: r.chat_id, text: text } };
});

// Record what happened to every report, so tomorrow's run and /status can see it.
const d = $('Assemble Market Data').first().json;
const s = $('Fact-Check AI Summary').first().json;
const sent = $('Compose Reports').all();
return $input.all().map((item, i) => ({ json: {
  chat_id: sent[i] ? sent[i].json.chat_id : '',
  report_date: d.today,
  trigger: d.mode,
  status: item.json.error ? 'failed' : 'sent',
  sections_down: d.sections_down || 'none',
  summary_by: s.summary_by + (s.summary_by === 'template' ? ' (' + s.check_note + ')' : ''),
  sent_at: new Date().toISOString()
} }));

// "Green is not a health check": a run that delivered nothing must fail loudly, not look successful.
const rows = $('Prepare Delivery Log').all().map(i => i.json);
const sent = rows.filter(r => r.status === 'sent').length;
return [{ json: { sent: sent, failed: rows.length - sent, nothing_delivered: rows.length > 0 && sent === 0 } }];
